        setValue(L.DESC_COMMAND_CHECK_SUMMARIES_RETURN, "JSON con el número de resúmenes y los desactualizados con las partes que cubren");
        setValue(L.DESC_COMMAND_GET_TEMPLATE_VARIABLES, "Muestra las variables de plantilla del libro o de una parte.");
        setValue(L.DESC_COMMAND_GET_TEMPLATE_VARIABLES_LLM, "Las variables que las plantillas de prompt definen con setvar: las globales del libro (scope global), o las de una parte, que siguen su rama (scope part; la última parte de la rama cuando no se da posición). Una parte se indica con su handle (el \"handle\" de las listas; no cambia cuando se añaden o eliminan partes, así que es preferible) o con su posición en una rama (la primera parte de la historia es 1); la rama es la activa a menos que se dé el handle de una parte de ella o un número de rama de list-branches. Solo lee. Las opciones son posicionales y opcionales, en el orden indicado.");
        setValue(L.DESC_COMMAND_GET_TEMPLATE_VARIABLES_RETURN, "JSON con las variables y sus valores");
