        setValue(L.DESC_COMMAND_TURN_SCENE_PARAM, "La ambientación de la escena del turno; vacío la borra, omitido la deja como está");
        setValue(L.DESC_COMMAND_TURN_POV_PARAM, "El personaje del punto de vista del turno; vacío lo borra, omitido lo deja como está");
        setValue(L.DESC_COMMAND_TURN_PRESENT_PARAM, "Los personajes presentes en el turno; vacío los borra, omitido los deja como están");
        setValue(L.DESC_COMMAND_EDIT_PART, "Reemplaza un fragmento del texto de una parte por otro texto. Parámetros: part (handle), old, new, field.");
        setValue(L.DESC_COMMAND_EDIT_PART_LLM, "Modifica una parte de la historia: el fragmento de texto `old` se reemplaza por `new`. `old` debe coincidir exactamente una vez en la parte (los mismos espacios y saltos de línea); si no, no se cambia nada y el error indica cuántas veces se encontró: incluye más texto de alrededor. La parte se indica con su handle. Cuenta sus palabras y tokens e indica qué resúmenes quedaron desactualizados (entonces ejecuta revalidate-summaries si siguen siendo correctos, o regenéralos). Con `field` se editan en su lugar las instrucciones, la escena, el punto de vista o los personajes presentes del turno. Modifica el libro.");
        setValue(L.DESC_COMMAND_EDIT_PART_RETURN, "JSON con la parte (handle, position, words, tokens) y los resúmenes que quedaron desactualizados");
        setValue(L.DESC_COMMAND_REPLACE_PART_TEXT, "Reemplaza todo el texto de una parte. Parámetros: part (handle), text, field.");
        setValue(L.DESC_COMMAND_REPLACE_PART_TEXT_LLM, "Reemplaza todo el texto de una parte de la historia por `text` (o todas las instrucciones, la escena, el punto de vista o los personajes presentes del turno con `field`). Se pierde el texto antiguo, así que para un cambio pequeño usa edit-part, y para añadir al final usa append-to-part. La parte se indica con su handle. Cuenta sus palabras y tokens e indica qué resúmenes quedaron desactualizados. Modifica el libro; se pide al usuario que confirme, y a un agente lo cubre su modo destructivo.");
        setValue(L.DESC_COMMAND_REPLACE_PART_TEXT_RETURN, "JSON con la parte (handle, position, words, tokens) y los resúmenes que quedaron desactualizados");
