        setValue(L.DESC_COMMAND_APPEND_TO_PART_LLM, "Añade `text` al final del texto de una parte de la historia, después de `separator` (una línea en blanco si se omite, nada cuando la parte está vacía). Úsalo para continuar una parte; para escribir una parte nueva usa create-part. La parte se indica con su handle. Cuenta sus palabras y tokens e indica qué resúmenes quedaron desactualizados. Modifica el libro.");
        setValue(L.DESC_COMMAND_APPEND_TO_PART_RETURN, "JSON con la parte (handle, position, words, tokens) y los resúmenes que quedaron desactualizados");
        setValue(L.DESC_COMMAND_SET_PART_FIELDS, "Cambia a partir de qué se creó una parte: instrucciones, escena, punto de vista y personajes presentes. Parámetros: part (handle), instructions, scene, pov, present.");
        setValue(L.DESC_COMMAND_SET_PART_FIELDS_LLM, "Cambia los datos de entrada del turno guardados con una parte de la historia: las instrucciones, la ambientación de la escena, el personaje del punto de vista y los personajes presentes, a partir de los cuales se vuelve a crear una nueva generación de la parte (variante, regeneración). Solo se cambian los campos que se dan; un texto vacío borra un campo. No cambia el texto de la parte. La parte se indica con su handle. Modifica el libro.");
        setValue(L.DESC_COMMAND_SET_PART_FIELDS_RETURN, "JSON con la parte y los datos de entrada del turno que tiene ahora");
