        setValue(L.DESC_COMMAND_CREATE_PART_LLM, "Añade a la historia una parte nueva con el texto dado: después de la parte `parent` (su handle), o después de la última parte de la rama activa cuando se omite `parent` (la primera parte de un libro vacío). Una parte que continúa una parte que ya tiene una continuación inicia una rama nueva. La parte nueva pasa a ser el final de la rama activa. Opcionalmente guarda los datos de entrada del turno (instructions, scene, pov, present) que representa. Úsalo para escribir texto tú mismo; para que lo escriba el modelo usa next. Modifica el libro. Devuelve el handle de la parte nueva.");
        setValue(L.DESC_COMMAND_CREATE_PART_RETURN, "JSON con la parte nueva (handle, position, words, tokens) y la longitud de la rama");
